INSERT INTO indicators (id, observatory_id, title, category_1, category_2, tags, unit, thematic_breakdown, geographic_breakdown, definition, calculation_formula, periodicity, baseline_date, delivery_form, source, source_link, actors, responsible_entity, observations, availability_status) VALUES (3102, 3, 'Área de acuíferos (sistema acuífero de Tunja) por municipio', 'Ecosistemas estratégicos y biodiversidad', 'Acuíferos', 'Observatorio Ambiental', 'Hectáreas', 'Municipio; Provincia; Unidad', 'Municipal y provincial', 'Superficie (hectáreas) de las unidades del sistema acuífero de Tunja y municipios vecinos, según la delimitación de CORPOBOYACÁ. Los acuíferos son reserva estratégica de agua subterránea para el abastecimiento humano y productivo.', 'Suma del área (ha) de los polígonos dentro de cada unidad territorial', 'Anual', '2020', 'Archivo remitido por la fuente / descarga del portal oficial', 'CORPOBOYACÁ', 'https://www.datos.gov.co/browse?q=CORPOBOYACA', 'Secretaría de Ambiente y Desarrollo Sostenible; Secretaría de Planeación; corporaciones autónomas regionales', 'Red de Observatorios de Boyacá – Secretaría Técnica', 'CORPOBOYACÁ – Sistema de Información Geográfica y bases de datos de expedientes (datos.gov.co), corte 2025', 'DISPONIBLE')
